/*
 * @test
 * @summary JVMS 6.5: each if_icmp* branch (if_icmpeq/ne/lt/ge/gt/le) at the
 *          signed-16-bit maximum forward offset +32767. Unlike CondBranchMatrix,
 *          which proves the comparison *semantics*, this test proves the offset
 *          boundary and branch direction: the taken path reaches the far target
 *          (returns 1) and the fall-through path returns 0. The class is
 *          generated byte-for-byte at run time and loaded through a fresh class
 *          loader, mirroring BranchBoundaryTest.
 *
 *          Each method's bytecode (opcode at offset 2, target 2+32767=32769):
 *            iload_0; iload_1; if_icmpXX +32767;
 *            iconst_0; ireturn;   // fall-through, returns 0
 *            [32762 nops];        // offsets 7..32768
 *            iconst_1; ireturn;   // target 32769, returns 1
 *          StackMapTable: same_frame_extended at offset 7 (dead code after the
 *          fall-through ireturn) and at offset 32769 (the branch target), deltas
 *          7 and 32769-7-1.
 * @run main IcmpBranchBoundaryTest
 */

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Files;
import java.nio.file.Path;

public class IcmpBranchBoundaryTest {
    static int passed;
    static void check(boolean c, String m) { if (c) passed++; else throw new AssertionError(m); }

    static void u1(DataOutputStream d, int v) throws Exception { d.writeByte(v); }
    static void u2(DataOutputStream d, int v) throws Exception { d.writeShort(v); }
    static void u4(DataOutputStream d, long v) throws Exception { d.writeInt((int) v); }
    static void utf8(DataOutputStream d, String s) throws Exception {
        u1(d, 1); byte[] b = s.getBytes("UTF-8"); u2(d, b.length); d.write(b);
    }

    static final int[] OPS = { 0x9F, 0xA0, 0xA1, 0xA2, 0xA3, 0xA4 }; // eq ne lt ge gt le

    static byte[] build() throws Exception {
        ByteArrayOutputStream o = new ByteArrayOutputStream();
        DataOutputStream d = new DataOutputStream(o);
        d.writeInt(0xCAFEBABE); u2(d, 0); u2(d, 52); // version 52 (JDK 8)

        // constant pool (17 entries, indices 1..17)
        u2(d, 18);
        utf8(d, "IcmpBranchBoundaryCls");                    // #1
        u1(d, 7); u2(d, 1);                                 // #2 Class #1
        utf8(d, "java/lang/Object");                        // #3
        u1(d, 7); u2(d, 3);                                 // #4 Class #3
        utf8(d, "<init>");                                  // #5
        utf8(d, "()V");                                     // #6
        utf8(d, "Code");                                    // #7
        utf8(d, "farIcmpeq");                               // #8
        utf8(d, "farIcmpne");                               // #9
        utf8(d, "farIcmplt");                               // #10
        utf8(d, "farIcmpge");                               // #11
        utf8(d, "farIcmpgt");                               // #12
        utf8(d, "farIcmple");                               // #13
        utf8(d, "(II)I");                                   // #14
        utf8(d, "StackMapTable");                           // #15
        u1(d, 12); u2(d, 5); u2(d, 6);                      // #16 NameAndType #5 #6
        u1(d, 10); u2(d, 4); u2(d, 16);                     // #17 Methodref #4 #16

        u2(d, 0x0021); u2(d, 2); u2(d, 4); u2(d, 0); u2(d, 0); // flags, this, super, ifaces, fields
        u2(d, 7);                                           // methods_count = 7

        // <init>()V
        u2(d, 0x0001); u2(d, 5); u2(d, 6); u2(d, 1);        // flags, name, desc, attrs=1
        u2(d, 7); u4(d, 12 + 5);                            // Code; fixed fields (12) + code (5)
        u2(d, 1); u2(d, 1);                                 // max_stack, max_locals
        u4(d, 5);                                           // code_length
        d.write(new byte[] { 0x2A, (byte) 0xB7, 0x00, 0x11, (byte) 0xB1 }); // aload_0; invokespecial #17; return
        u2(d, 0); u2(d, 0);                                 // exc_table_len, code_attrs

        // farIcmpeq..farIcmple (II)I
        int[] names = { 8, 9, 10, 11, 12, 13 };
        for (int i = 0; i < 6; i++) {
            u2(d, 0x0009); u2(d, names[i]); u2(d, 14); u2(d, 1); // public static, name, desc, attrs=1
            int codeLen = 1 + 1 + 3 + 1 + 1 + 32762 + 1 + 1;     // 32771
            u2(d, 7); u4(d, 12 + codeLen + 14);                  // Code; fixed(12)+code+StackMapTable(14)
            u2(d, 2); u2(d, 2);                                  // max_stack=2, max_locals=2
            u4(d, codeLen);
            d.write(0x1A); d.write(0x1B);                        // iload_0; iload_1 (offsets 0..1)
            d.write(OPS[i]); u2(d, 32767);                       // if_icmpXX +32767 (opcode at 2, target 32769)
            d.write(0x03); d.write(0xAC);                        // iconst_0; ireturn (fall-through, returns 0)
            for (int j = 0; j < 32762; j++) d.write(0x00);       // nops (offsets 7..32768)
            d.write(0x04); d.write(0xAC);                        // iconst_1; ireturn (target 32769, returns 1)
            u2(d, 0); u2(d, 1);                                  // exc_table_len=0, code_attrs=1
            u2(d, 15); u4(d, 8);                                 // StackMapTable; 2 entries
            u2(d, 2); d.write(251); u2(d, 7);                    // same_frame_extended @ 7
            d.write(251); u2(d, 32761);                          // same_frame_extended @ 32769 (delta=32769-7-1)
        }

        u2(d, 0);                                           // class-level attributes_count = 0
        return o.toByteArray();
    }

    static Class<?> load(String name, byte[] b) throws Exception {
        Path dir = Files.createTempDirectory("cls");
        Files.write(dir.resolve(name + ".class"), b);
        URLClassLoader cl = new URLClassLoader(new URL[]{ dir.toUri().toURL() }, null);
        return Class.forName(name, true, cl);
    }

    static int invoke(Class<?> c, String m, int a, int b) throws Exception {
        return (Integer) c.getMethod(m, int.class, int.class).invoke(null, a, b);
    }

    public static void main(String[] args) throws Exception {
        Class<?> c = load("IcmpBranchBoundaryCls", build());
        check(invoke(c, "farIcmpeq", 3, 3) == 1 && invoke(c, "farIcmpeq", 3, 4) == 0, "if_icmpeq +32767");
        check(invoke(c, "farIcmpne", 3, 4) == 1 && invoke(c, "farIcmpne", 3, 3) == 0, "if_icmpne +32767");
        check(invoke(c, "farIcmplt", 3, 4) == 1 && invoke(c, "farIcmplt", 3, 3) == 0, "if_icmplt +32767");
        check(invoke(c, "farIcmpge", 4, 4) == 1 && invoke(c, "farIcmpge", 3, 4) == 0, "if_icmpge +32767");
        check(invoke(c, "farIcmpgt", 4, 3) == 1 && invoke(c, "farIcmpgt", 4, 4) == 0, "if_icmpgt +32767");
        check(invoke(c, "farIcmple", 3, 4) == 1 && invoke(c, "farIcmple", 4, 3) == 0, "if_icmple +32767");
        System.out.println("PASS (" + passed + " assertions)");
    }
}
